import{_ as o,o as t,c as a,a6 as r}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"让 MoE 训得稳、又均衡","description":"MoE 的命门是负载均衡——路由器爱偏心，把 token 全塞给少数热门专家，其余饿死。传统靠“辅助损失”硬掰，但它会干扰主目标、伤性能。看 DeepSeek 的“无辅助损失均衡”如何用一个动态偏置优雅解决，以及为什么头几层要保持稠密。","frontmatter":{"title":"让 MoE 训得稳、又均衡","description":"MoE 的命门是负载均衡——路由器爱偏心，把 token 全塞给少数热门专家，其余饿死。传统靠“辅助损失”硬掰，但它会干扰主目标、伤性能。看 DeepSeek 的“无辅助损失均衡”如何用一个动态偏置优雅解决，以及为什么头几层要保持稠密。","source":"https://daiw.org/manual/llm-anatomy/moe-stability"},"headers":[],"relativePath":"manual/llm/llm-anatomy/moe-stability.md","filePath":"manual/llm/llm-anatomy/moe-stability.md"}'),n={name:"manual/llm/llm-anatomy/moe-stability.md"};function l(s,e,i,g,p,m){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="让-moe-训得稳、又均衡" tabindex="-1">让 MoE 训得稳、又均衡 <a class="header-anchor" href="#让-moe-训得稳、又均衡" aria-label="Permalink to &quot;让 MoE 训得稳、又均衡&quot;">​</a></h1><blockquote><p>MoE 的命门是负载均衡——路由器爱偏心，把 token 全塞给少数热门专家，其余饿死。传统靠“辅助损失”硬掰，但它会干扰主目标、伤性能。看 DeepSeek 的“无辅助损失均衡”如何用一个动态偏置优雅解决，以及为什么头几层要保持稠密。</p></blockquote><p>MoE 有个众所周知的老大难，不解决，几百个专家就是摆设。这一章讲这个命门——<strong>负载均衡</strong>——以及 DeepSeek 一个特别漂亮的解法。</p><h2 id="命门-路由器天生爱偏心" tabindex="-1">命门：路由器天生爱偏心 <a class="header-anchor" href="#命门-路由器天生爱偏心" aria-label="Permalink to &quot;命门：路由器天生爱偏心&quot;">​</a></h2><p>MoE 靠路由器给每个 token 挑专家。问题是，<strong>路由器会“马太效应”</strong>：某个专家一开始碰巧表现好、被选得多，就练得更好，于是被选得更多……最后<strong>少数几个热门专家垄断了几乎所有 token，剩下几百个专家门可罗雀、学不到东西</strong>。</p><p>这叫<strong>负载不均衡（load imbalance）</strong>，后果很严重：</p><ol><li><strong>容量浪费</strong>：你设了 256 个专家，实际干活的没几个，等于白堆参数。</li><li><strong>训练不稳 / 设备闲忙不均</strong>：大模型的专家是<strong>分散在多张卡上</strong>的（专家并行）。热门专家所在的卡被打爆、冷门专家的卡在摸鱼，整体吞吐被最忙的卡拖死。</li></ol><p>所以**“让 token 尽量均匀地分给各专家”**，是 MoE 能不能训好的头等大事。</p><h2 id="老办法-辅助损失-有副作用" tabindex="-1">老办法：辅助损失（有副作用） <a class="header-anchor" href="#老办法-辅助损失-有副作用" aria-label="Permalink to &quot;老办法：辅助损失（有副作用）&quot;">​</a></h2><p>Switch Transformer、GShard 那代的标准解法，是加一个<strong>辅助损失（auxiliary load-balancing loss）</strong>：在主训练目标之外，额外加一个惩罚项，<strong>谁分配不均就罚谁</strong>，逼着路由器把 token 摊平。</p><p>管用，但有<strong>副作用</strong>。这个辅助损失会往模型里<strong>注入额外的梯度</strong>，而这些梯度的目标（“务必均匀”）<strong>和主目标（“把话说好”）未必一致</strong>——有时候某个 token 本该重点交给某个专家最合适，辅助损失却为了“均匀”硬把它匀走。于是<strong>均衡是达到了，模型质量却被拖累了</strong>。这是一种“按下葫芦浮起瓢”的妥协。</p><h2 id="deepseek-的巧劲-无辅助损失均衡" tabindex="-1">DeepSeek 的巧劲：无辅助损失均衡 <a class="header-anchor" href="#deepseek-的巧劲-无辅助损失均衡" aria-label="Permalink to &quot;DeepSeek 的巧劲：无辅助损失均衡&quot;">​</a></h2><p>DeepSeek 在 <strong>《Auxiliary-Loss-Free Load Balancing》（Wang et al.，2024）</strong> 里提出了一个漂亮得多的办法，并用在了 DeepSeek-V3 上。核心一句话：</p><blockquote><p><strong>不用“损失”去掰，而是给每个专家的路由得分加一个可动态调节的“偏置（bias）”——谁太闲就把它的偏置调高一点（更容易被选中），谁太忙就调低一点。均衡靠这个“调节旋钮”实现，完全不碰主损失。</strong></p></blockquote><p>打个比方：老办法像是<strong>给挑食的孩子立个规矩、写进考卷里扣分</strong>（规矩会干扰他好好答题）；新办法像是<strong>食堂根据排队长短，悄悄把冷清窗口的菜价调便宜一点</strong>——顾客自然被引导着分流，而没人被扣分、没人被强迫。</p><p>好处是决定性的：</p><ul><li><strong>不注入干扰主目标的梯度</strong> → 模型质量不受损；</li><li>偏置只影响“选谁”，不改专家算出来的值，所以<strong>均衡和质量不再打架</strong>。</li></ul><p>DeepSeek 的实验显示：<strong>无辅助损失均衡，既比辅助损失方案更均衡，模型还更好。</strong> 这是个“既要又要”都拿到的少见案例，也难怪 GLM-4.5、<a href="https://daiw.org/manual/kimi-k3/moe-stability" target="_blank" rel="noreferrer">Kimi K3</a>（配置文件中直接标记为 <code>topk_method: &quot;noaux_tc&quot;</code>，配合 Sigmoid 路由打分与零初始化专家输出投影）等后来者纷纷跟进。到了 2026 年的原生多模态模型 <a href="https://daiw.org/manual/deepseek-v4-flash/multimodal" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash</a>，这套无辅助损失均衡还进一步升级为<strong>分模态负载均衡偏置</strong>：给文本 token 和视觉 token 各自维护一套独立的动态偏置，既保证每种模态内部算力打满，又允许模型自发分化出“视觉专精专家”和“文本专精专家”。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>实践里还有些配套的稳定性细节，顺带一提：路由打分常用 <strong>fp32 高精度</strong>计算（路由对数值抖动敏感）；以及<strong>专家容量</strong>上限——当某个专家这一批收到的 token 超过容量，多出来的会被丢弃或改道，防止个别专家被瞬间打爆。这些都是让 MoE“训得动”的工程护栏。</p></div><h2 id="另一个稳定性招-头几层保持稠密" tabindex="-1">另一个稳定性招：头几层保持稠密 <a class="header-anchor" href="#另一个稳定性招-头几层保持稠密" aria-label="Permalink to &quot;另一个稳定性招：头几层保持稠密&quot;">​</a></h2><p>还有一个各家不约而同的小设计：<strong>模型最前面的几层不做 MoE，保持稠密</strong>。</p><ul><li><strong>DeepSeek-V3 / V4.1-Flash</strong>：前 3 层稠密，之后才上 MoE；</li><li><strong>GLM-4.5</strong>：同样借鉴了“前几层稠密”的做法；</li><li><strong>Kimi K3 / K3.1 Pro</strong>：第 0 层为稠密 MLP（<code>first_k_dense_replace: 1</code>），第 1–92 层为 LatentMoE。</li></ul><p>为什么？<strong>最靠近输入的那几层，处理的是最基础、最共性的特征（词形、局部搭配），这些“人人都要”的东西本就不该被路由分流</strong>；而且训练早期路由器还很“懵”，让它在第一层就对着几百个专家瞎分，容易带偏整个训练。<strong>先用稳定的稠密层把地基打牢，再在上面放稀疏的 MoE</strong>，收敛更稳。这是个便宜又有效的“稳定器”。</p><h2 id="小结-moe-的两条主线到此收束" tabindex="-1">小结：MoE 的两条主线到此收束 <a class="header-anchor" href="#小结-moe-的两条主线到此收束" aria-label="Permalink to &quot;小结：MoE 的两条主线到此收束&quot;">​</a></h2><p>把 MoE 这三章连起来看：</p><ul><li><strong>稠密 vs 稀疏</strong>（为什么用 MoE）：解耦“容量”和“算力”；</li><li><strong>三个旋钮</strong>（怎么设计 MoE）：专家多而小 / 少而大、激活几个、要不要共享；</li><li><strong>稳定与均衡</strong>（怎么训好 MoE）：从辅助损失到 DeepSeek 的无辅助损失，加上头几层稠密。</li></ul><p>至此，这一代大模型的**两条主战场（省 KV 缓存、稀疏化 MoE）**都讲完了。它们决定了一个模型“推理烧多少显存、每步算多少”这两个最要命的数字。</p><p>接下来几章，是重要但不改大局的“配角维度”。第一个，是一个看似不起眼、却实实在在左右训练能不能稳住的选择——<strong>归一化到底放哪儿</strong>。👉 <a href="/Front2Full/manual/llm/llm-anatomy/normalization">归一化：RMSNorm、Pre / Post / 三明治、QK-Norm</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Wang et al. (DeepSeek). “Auxiliary-Loss-Free Load Balancing Strategy for Mixture-of-Experts.” 2024. arXiv:2408.15664. —— 无辅助损失均衡。</li><li>[2] Fedus et al. “Switch Transformers.” JMLR 2022. arXiv:2101.03961. —— 辅助负载均衡损失。</li><li>[3] Zoph et al. “ST-MoE: Designing Stable and Transferable Sparse Expert Models.” 2022. arXiv:2202.08906. —— MoE 训练稳定性的系统研究。</li><li>[4] DeepSeek-AI. “DeepSeek-V3 Technical Report.” 2024. arXiv:2412.19437. —— 无辅助损失均衡 + 前几层稠密的实际应用。</li></ul>',30)])])}const h=o(n,[["render",l]]);export{c as __pageData,h as default};
